=== ui.js ===
// The bits every view needs: DOM helpers, the icon set, and the mutable state.
//
// State lives in one object rather than being threaded through every function, and `S.render`
// / `S.status` / `S.push` are slots the shell fills in, so a view can ask for a redraw or a
// background push without importing app.js back.
import {
  todayKey, DEFAULT_ANCHOR, groupColor, groupLabel, monthGrid, weekStartOf, addDays, partsOf,
  sprintRange, sprintOf
} from './data.js';
import { formatDate, weekdayName } from '../shared/prefs.js';

export const $ = s => document.querySelector(s);
export const el = (tag, cls, text) => {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
};
export const phone = () => !matchMedia('(min-width: 600px)').matches;

export const S = {
  model: { groups: {}, dated: [], rules: [], overrides: new Map(),
           settings: { anchor: DEFAULT_ANCHOR, interval: 2 } },
  view: { mode: 'M', anchor: todayKey(), sprint: 1, col: 0 },
  prefs: { weekStart: 1, showWeeks: false, timeZone: '', theme: 'system', dateFormat: 'auto' },
  hidden: new Set(),                 // group names switched off in the filter
  kfilter: { priority: new Set(), assignee: '' },   // kanban only
  visible: new Map(),                // occurrence key -> occurrence, for what is on screen
  render: () => {},
  status: () => {},
  push: () => {},
  reload: async () => S.model
};

export const colorOf = g => groupColor(S.model.groups, g);
export const labelOf = g => groupLabel(S.model.groups, g);
export const dayLabel = key => formatDate(key, S.prefs.dateFormat);
export const longDayLabel = key => `${weekdayName(key)}, ${formatDate(key, S.prefs.dateFormat)}`;

// Text on a group-coloured background. Luminance rather than a fixed colour, because the
// groups are user-chosen and a light one would otherwise carry white text.
export function inkOn(hex) {
  const h = String(hex).replace('#', '');
  const n = h.length === 3 ? h.split('').map(c => c + c).join('') : h.slice(0, 6);
  const [r, g, b] = [0, 2, 4].map(i => parseInt(n.slice(i, i + 2), 16) / 255 || 0);
  const lum = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  return lum > 0.6 ? '#1b1f24' : '#fff';
}

// The inclusive day range the current view shows.
export function viewRange() {
  const { mode, anchor, sprint } = S.view;
  if (mode === 'D') return [anchor, anchor];
  if (mode === 'W') { const a = weekStartOf(anchor, S.prefs.weekStart); return [a, addDays(a, 6)]; }
  if (mode === 'M') {
    const [y, m] = partsOf(anchor);
    const g = monthGrid(y, m - 1, S.prefs.weekStart);
    return [g[0], g[g.length - 1]];
  }
  if (mode === 'Y') { const [y] = partsOf(anchor); return [`${y}-01-01`, `${y}-12-31`]; }
  const r = sprintRange(sprint, S.model.settings);
  return [r.start, r.end];
}

// Where a new entry lands: today when today is in view, otherwise the first day on screen.
export function defaultDay() {
  const [from, to] = viewRange();
  const t = todayKey();
  return t >= from && t <= to ? t : from;
}

export const currentSprint = () => sprintOf(todayKey(), S.model.settings) || 1;

// ---- icons ---------------------------------------------------------------------------------
// Hand-drawn on a 16x16 box. No icon font and no CDN: the CSP allows neither, and an inline
// path cannot fail to load.

const NS = 'http://www.w3.org/2000/svg';
const ICON = {
  repeat: { d: 'M2.6 8.4A5.4 5.4 0 0 1 12.6 5.6M13.4 7.6A5.4 5.4 0 0 1 3.4 10.4M12.9 2.6v3.2H9.7M3.1 13.4v-3.2h3.2', stroke: 1.5 },
  ball:   { d: 'M8 2.6a5.4 5.4 0 1 0 0 10.8A5.4 5.4 0 0 0 8 2.6z' },
  pin:    { d: 'M8 1.4a4.4 4.4 0 0 0-4.4 4.4C3.6 9.2 8 14.6 8 14.6s4.4-5.4 4.4-8.8A4.4 4.4 0 0 0 8 1.4zm0 6a1.6 1.6 0 1 1 0-3.2 1.6 1.6 0 0 1 0 3.2z' },
  bell:   { d: 'M8 1.6a3.6 3.6 0 0 0-3.6 3.6v2.6L2.8 10.4h10.4L11.6 7.8V5.2A3.6 3.6 0 0 0 8 1.6zM6.3 11.6a1.8 1.8 0 0 0 3.4 0z' },
  person: { d: 'M8 2.2a2.6 2.6 0 1 1 0 5.2 2.6 2.6 0 0 1 0-5.2zM2.4 14c0-3.1 2.5-4.9 5.6-4.9s5.6 1.8 5.6 4.9z' },
  trash:  { d: 'M6.2 1.6h3.6l.6 1.2h2.8v1.5H2.8V2.8h2.8l.6-1.2zM3.9 5.6h8.2l-.7 8.8H4.6z' },
  disk:   { d: 'M2.6 2h8.2L14 5.2V14H2.6zm3 0v3.6h4.6V2zM5 9h6v5H5z' },
  pen:    { d: 'M11.6 1.8l2.6 2.6-8 8-3.4.8.8-3.4z' },
  plus:   { d: 'M8 3v10M3 8h10', stroke: 1.8 },
  x:      { d: 'M4 4l8 8M12 4l-8 8', stroke: 1.8 },
  filter: { d: 'M2 3h12l-4.8 5.8V14L6.8 12.6V8.8z' },
  chev:   { d: 'M10 3.5 5.5 8l4.5 4.5', stroke: 1.8 }
};

export function icon(name) {
  const spec = ICON[name];
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 16 16');
  svg.setAttribute('aria-hidden', 'true');
  const p = document.createElementNS(NS, 'path');
  p.setAttribute('d', spec.d);
  if (spec.stroke) {
    p.setAttribute('fill', 'none');
    p.setAttribute('stroke', 'currentColor');
    p.setAttribute('stroke-width', String(spec.stroke));
    p.setAttribute('stroke-linecap', 'round');
    p.setAttribute('stroke-linejoin', 'round');
  } else p.setAttribute('fill', 'currentColor');
  svg.append(p);
  return svg;
}

// `name` is an icon name, or any other string to use as a glyph - T, E, D and the gear are
// letters in the design, not drawings.
export function iconBtn(name, label, cls = '') {
  const b = el('button', ['ib', cls].filter(Boolean).join(' '));
  b.type = 'button';
  b.title = label;
  b.setAttribute('aria-label', label);
  b.append(ICON[name] ? icon(name) : el('span', 'glyph', name));
  return b;
}

// ---- popovers ------------------------------------------------------------------------------

export function openPop(pop, anchor, align = 'left') {
  pop.hidden = false;
  $('#scrim').hidden = false;
  const r = anchor.getBoundingClientRect();
  const w = pop.offsetWidth;
  const left = align === 'right' ? r.right - w : r.left;
  pop.style.left = `${Math.max(8, Math.min(left, innerWidth - w - 8))}px`;
  pop.style.top = `${r.bottom + 6}px`;
  anchor.setAttribute?.('aria-expanded', 'true');
}

const POPS = ['#picker', '#filter-pop', '#day-pop', '#settings-sheet'];

export function closePops() {
  for (const id of [...POPS, '#scrim']) $(id).hidden = true;
  for (const id of ['#period', '#filter-btn']) $(id).setAttribute('aria-expanded', 'false');
}

=== calendar/style.css ===
/* Calendar. Phone first: the desktop grid is the enhancement, not the other way round. Every
   view shows seven columns beginning with the configured first day of the week, and a month
   cell carries titled lines rather than dots - a Saturday task has to be readable. */

/* An id or class rule for display beats the UA stylesheet's [hidden], so #cal and the modal
   would both render while still carrying the attribute. */
[hidden] { display: none !important; }

:root { --cell: 3.3rem; --today: #1f66d0; --hour: 2.4rem; --gutter: 2rem; --tcol: 3rem; }
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) { --today: #6ea8ff; } }
:root[data-theme="dark"] { --today: #6ea8ff; }

body { max-width: none; padding: 0; padding-bottom: env(safe-area-inset-bottom); }
#cal { display: flex; flex-direction: column; min-height: 100vh; min-height: 100dvh; }

/* ---- top pane ---- */
.topbar {
  position: sticky; top: 0; z-index: 5;
  display: flex; flex-wrap: wrap; align-items: center; gap: .3rem;
  padding: max(.5rem, env(safe-area-inset-top)) .5rem .5rem;
  background: var(--bg); border-bottom: 1px solid var(--line);
}
.topbar .spacer { flex: 1; }
.nav {
  display: inline-flex; align-items: center; justify-content: center;
  width: auto; min-width: 2.2rem; min-height: 2.2rem; margin: 0; padding: .3rem .5rem;
  font-size: 1.05rem; line-height: 1; font-weight: 500; text-decoration: none;
  color: var(--fg); background: var(--soft); border: 0; border-radius: .5rem;
}
.nav.wide { font-size: .8rem; padding: .5rem .6rem; }
.nav.ic svg { width: 1.05rem; height: 1.05rem; display: block; }
.period {
  width: auto; margin: 0; padding: .4rem .5rem; font-size: .95rem; font-weight: 600;
  color: var(--fg); background: none; border: 0; white-space: nowrap;
}
.caret { margin-left: .3rem; font-size: .7rem; opacity: .6; }

.modes { display: flex; }
.mode {
  width: auto; min-width: 1.7rem; margin: 0; padding: .45rem .2rem;
  font-size: .76rem; font-weight: 700; line-height: 1;
  color: var(--fg); background: var(--soft); border: 0; border-radius: 0;
}
.mode:first-child { border-radius: .5rem 0 0 .5rem; }
.mode:last-child { border-radius: 0 .5rem .5rem 0; }
.mode[aria-pressed="true"] { color: var(--bg); background: var(--accent); }

.view { flex: 1; min-height: 0; }
.sync { padding: .4rem .7rem; margin: 0; font-size: .75rem; }

/* ---- month ---- */
.weekhead {
  display: grid; grid-template-columns: repeat(7, 1fr);
  padding: .35rem .25rem 0; font-size: .7rem; font-weight: 600;
  color: var(--muted); text-align: center; text-transform: uppercase; letter-spacing: .04em;
}
.weekhead.gut, .grid.gut { grid-template-columns: var(--gutter) repeat(7, 1fr); }
.weekhead span.we { color: var(--today); }

.grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 1px; padding: .25rem; }
/* The week number, separated from the days by a thin vertical rule. Always ISO. */
.wk {
  display: flex; align-items: center; justify-content: center;
  font-size: .6rem; font-variant-numeric: tabular-nums; color: var(--muted);
  border-right: 1px solid var(--line);
}
.day {
  display: flex; flex-direction: column; align-items: stretch; gap: .1rem;
  min-height: var(--cell); padding: .15rem .12rem;
  text-align: left; color: var(--fg); background: var(--bg); border-radius: .3rem; cursor: pointer;
}
.day.we { background: var(--soft); }
.day.out { opacity: .4; }
.num {
  align-self: center; min-width: 1.5rem; padding: .1rem 0;
  font-size: .76rem; font-variant-numeric: tabular-nums; text-align: center;
  color: var(--muted); border-radius: 999px;
}
.day.today .num { color: #fff; background: var(--today); font-weight: 700; }

.rows { display: flex; flex-direction: column; gap: 1px; overflow: hidden; }
.eline {
  display: flex; align-items: center; gap: .2rem;
  padding: .06rem .22rem; font-size: .66rem; line-height: 1.3;
  border-radius: .22rem; cursor: pointer;
}
.eline .when { flex: none; font-variant-numeric: tabular-nums; opacity: .8; }
.eline .what { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.eline.done .what { text-decoration: line-through; opacity: .75; }
.more { font-size: .6rem; color: var(--muted); padding-left: .2rem; }

/* The rectangular icon that moves a task straight to done. */
.tick {
  flex: none; width: .95rem; height: .72rem; margin: 0; padding: 0;
  background: none; border: 1.5px solid currentColor; border-radius: 2px;
  opacity: .75; cursor: pointer;
}
.tick.on { background: currentColor; opacity: 1; }

/* ---- year ---- */
.year {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(10.5rem, 1fr));
  gap: .7rem; padding: .5rem;
}
.ycap { font-size: .8rem; font-weight: 600; margin-bottom: .25rem; }
.ygrid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 1px; }
.ywh { font-size: .55rem; color: var(--muted); text-align: center; text-transform: uppercase; }
.ywh.we { color: var(--today); }
.yday {
  width: auto; margin: 0; padding: .2rem 0;
  font-size: .62rem; font-variant-numeric: tabular-nums; font-weight: 500;
  color: var(--fg); background: none; border: 0; border-radius: .2rem; cursor: pointer;
}
.yday.out { visibility: hidden; }
.yday.today { outline: 2px solid var(--today); outline-offset: -2px; font-weight: 700; }

/* ---- week and day: columns are the days, rows are the 24 hours ---- */
.tg { display: flex; flex-direction: column; height: 100%; min-height: 0; }
.tg-head, .tg-allday, .tg-body {
  display: grid; grid-template-columns: var(--tcol) repeat(var(--cols), 1fr);
}
.tg-head { border-bottom: 1px solid var(--line); }
.tcorner { font-size: .6rem; color: var(--muted); align-self: center; text-align: center; }
.tgd { padding: .3rem 0; text-align: center; cursor: pointer; }
.tgd.we { background: var(--soft); }
.tgd .dw { display: block; font-size: .62rem; color: var(--muted); text-transform: uppercase; }
.tgd .dn { display: block; font-size: .95rem; font-weight: 600; }
.tgd.today .dn { color: var(--today); }

.tg-allday { border-bottom: 1px solid var(--line); }
.adcell {
  display: flex; flex-direction: column; gap: 1px; min-height: 1.5rem; padding: 2px;
  border-left: 1px solid var(--line); cursor: pointer;
}
.adcell.we { background: var(--soft); }

.tg-body { flex: 1; min-height: 0; overflow-y: auto; }
.hours { display: grid; grid-template-rows: repeat(24, var(--hour)); }
.hr {
  font-size: .58rem; color: var(--muted); text-align: right; padding-right: .25rem;
  font-variant-numeric: tabular-nums;
}
.tcol {
  position: relative; height: calc(24 * var(--hour));
  border-left: 1px solid var(--line); cursor: pointer;
  background: repeating-linear-gradient(to bottom, var(--line) 0 1px, transparent 1px var(--hour));
}
.tcol.we { background-color: var(--soft); }
.tev {
  position: absolute; left: 2px; right: 2px; min-height: 1rem; overflow: hidden;
  padding: .1rem .3rem; font-size: .68rem; line-height: 1.25;
  border-radius: .3rem; cursor: pointer;
}
.tev .when { display: block; font-variant-numeric: tabular-nums; opacity: .85; }
.tev .what { display: block; font-weight: 600; }
.tev .meta { display: block; font-size: .62rem; opacity: .85; }
.tev.done .what { text-decoration: line-through; }
.tev .tick { position: absolute; top: .22rem; right: .22rem; }

/* ---- kanban ---- */
.kb { display: grid; grid-template-columns: repeat(3, 1fr); gap: .5rem; padding: .5rem; }
.view.vK.one { overflow: hidden; }
.one .kb {
  grid-template-columns: repeat(3, 100%);
  transform: translateX(calc(var(--col) * -100%)); transition: transform .18s ease-out;
}
.kcol {
  display: flex; flex-direction: column; gap: .4rem;
  padding: .4rem; background: var(--soft); border-radius: .6rem;
}
.khead { display: flex; align-items: center; gap: .4rem; font-size: .8rem; font-weight: 600; }
.kdot { flex: none; width: .6rem; height: .6rem; border-radius: 999px; }
.kname { text-transform: capitalize; }
.kcount { margin-left: auto; font-size: .75rem; color: var(--muted); }
.kcards { display: flex; flex-direction: column; gap: .4rem; }
.kcard {
  display: flex; gap: .4rem; padding: .4rem;
  background: var(--bg); border: 1px solid var(--line); border-radius: .5rem;
}
.kbar { flex: none; width: 3px; border-radius: 2px; }
.kmain { flex: 1; min-width: 0; }
.ktop { display: flex; align-items: center; gap: .1rem; }
.ktitle {
  flex: 1; min-width: 0; padding: 0 .2rem; font-size: .85rem; font-weight: 600;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.kbody {
  margin: .25rem 0 0; font-size: .72rem; color: var(--muted); overflow: hidden;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
}
.kwhen { margin: .2rem 0 0; font-size: .64rem; color: var(--muted); }
.kchips { display: flex; flex-direction: column; align-items: flex-end; gap: .2rem; }
.chip {
  width: auto; margin: 0; padding: .14rem .36rem; font-size: .64rem; font-weight: 700;
