import http.server, json, os, sys

REPO = "/home/max/ws/mine"
PORT = int(sys.argv[1]) if len(sys.argv) > 1 else 8787

def entry(day, time, title, group, kind, stage=None, dur=1):
    key = "2026-11-%02d" % day
    fm = ['title: "%s"' % title, "type: " + kind]
    if time:
        fm.append("start: %sT%s:00Z" % (key, time))
        fm.append("end: %sT%02d:%s:00Z" % (key, int(time[:2]) + dur, time[3:]))
    else:
        fm.append("start: " + key)
    fm.append("group: " + group)
