const PORT = 8787, CDP = 9222, ORIGIN = `http://127.0.0.1:${PORT}`;
const sleep = ms => new Promise(r => setTimeout(r, ms));
const l = await (await fetch(`http://127.0.0.1:${CDP}/json/list`)).json();
const ws = new WebSocket(l.find(t => t.type === 'page').webSocketDebuggerUrl);
await new Promise(r => ws.addEventListener('open', r));
let id = 0; const waiting = new Map();
ws.addEventListener('message', e => { const m = JSON.parse(e.data);
  if (m.id && waiting.has(m.id)) { waiting.get(m.id)(m); waiting.delete(m.id); } });
const send = (method, params = {}) => new Promise((res, rej) => { const n = ++id;
  waiting.set(n, m => m.error ? rej(new Error(m.error.message)) : res(m.result));
  ws.send(JSON.stringify({ id: n, method, params })); });
const ev = async expression => {
  const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description);
  return r.result.value; };
await send('Page.enable'); await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 860, deviceScaleFactor: 1, mobile: true });
await send('Page.navigate', { url: `${ORIGIN}/calendar/` });
await sleep(1700);

const before = await ev(`(async () => (await new Promise(r => {
  const q = indexedDB.open('mine', 1); q.onsuccess = () => {
    const t = q.result.transaction('files','readonly').objectStore('files').getAllKeys();
    t.onsuccess = () => r(t.result); }; })).length)()`);

// A brand-new task, saved with nothing but a title touched.
await ev(`document.querySelector('#add').click()`); await sleep(350);
await ev(`document.querySelectorAll('#f-icons .ib')[0].click()`); await sleep(250);
await ev(`const i = document.querySelector('#f-title');
  i.value = 'Grout the shower';
  i.dispatchEvent(new Event('input', {bubbles:true}))`);
await sleep(150);
await ev(`document.querySelector('#entry-form').requestSubmit()`);
await sleep(1200);

const written = await ev(`(async () => {
  const keys = await new Promise(r => { const q = indexedDB.open('mine', 1); q.onsuccess = () => {
    const t = q.result.transaction('files','readonly').objectStore('files').getAll();
    t.onsuccess = () => r(t.result); }; });
  const f = keys.find(f => (f.text||'').includes('Grout the shower'));
  return f ? { path: f.path, text: f.text } : 'not written';
})()`);
console.log('files before:', before);
console.log(JSON.stringify(written, null, 1));

// And a task saved with the estimate cleared.
await ev(`document.querySelector('#add').click()`); await sleep(350);
await ev(`document.querySelectorAll('#f-icons .ib')[0].click()`); await sleep(250);
await ev(`document.querySelectorAll('#f-icons .ib')[4].click()`); await sleep(300);
await ev(`document.querySelector('#sub-clear').click()`); await sleep(300);
await ev(`const i = document.querySelector('#f-title');
  i.value = 'No estimate please';
  i.dispatchEvent(new Event('input', {bubbles:true}))`);
await sleep(150);
await ev(`document.querySelector('#entry-form').requestSubmit()`);
await sleep(1200);
console.log(JSON.stringify(await ev(`(async () => {
  const all = await new Promise(r => { const q = indexedDB.open('mine', 1); q.onsuccess = () => {
    const t = q.result.transaction('files','readonly').objectStore('files').getAll();
    t.onsuccess = () => r(t.result); }; });
  const f = all.find(f => (f.text||'').includes('No estimate please'));
  return f ? f.text : 'not written';
})()`), null, 1));
ws.close();
EOF
